    private fun icon(sourceName: String, paths: ImageVector.Builder.() -> Unit): ImageVector =
        ImageVector.Builder(
            name = sourceName,
            defaultWidth = 32.dp,
            defaultHeight = 32.dp,
            viewportWidth = 32f,
            viewportHeight = 32f,
        ).apply(paths).build()

    private fun ImageVector.Builder.fillPath(data: String) {
        addPath(
            pathData = PathParser().parsePathString(data).toNodes(),
            pathFillType = PathFillType.NonZero,
            fill = SolidColor(Color.Black),
        )
    }

    private fun ImageVector.Builder.strokePath(data: String, cap: StrokeCap, join: StrokeJoin) {
        addPath(
            pathData = PathParser().parsePathString(data).toNodes(),
            stroke = SolidColor(Color.Black),
            strokeLineWidth = 1f,
            strokeLineCap = cap,
            strokeLineJoin = join,
        )
    }

